// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 amount, address recipient) public {
        vm.assume(amount > 0);
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        vm.deal(address(c), amount);
        uint256 contractBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;
        c.withdrawAll(recipient);
        uint256 contractBalanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = recipient.balance;
        assertTrue(contractBalanceAfter == 0 && recipientBalanceAfter == recipientBalanceBefore + contractBalanceBefore);
    }
}
